let LANG=(function(){try{const v=JSON.parse(localStorage.getItem('tr-lang')||'null');return LANGS.some(l=>l[0]===v)?v:null;}catch(e){return null;}})();
function lang(){return LANG||'en';}
function LX(s){const L=LANG&&LANG!=='en'?UI18N[LANG]:null;return (L&&L[s])||s;}
// Devanagari → Telugu / Kannada: the Brahmic blocks line up, so a fixed offset maps each letter
function devTo(dev,l){const off=l==='te'?0x300:l==='kn'?0x380:0;if(!off)return dev;let o='';for(const ch of dev){const c=ch.codePointAt(0);o+=(c>=0x0901&&c<=0x094D)||(c>=0x0958&&c<=0x0963)||(c>=0x0966&&c<=0x096F)?String.fromCodePoint(c+off):ch;}return o;}
// a tattva in the current language
function TL(n){const T=TATTVAS[n-1],l=lang(),X=l!=='en'&&TI18N[l]?TI18N[l]:null,x=X?X.t[n-1]:null;
 const four=T.dev.length>=4,dev=four?T.dev.slice(0,4):T.dev.concat([L4.dev]),iast=four?T.iast.slice(0,4):T.iast.concat([L4.iast]);
 return{n:T.n,name:x?x.name:T.name,teach:x?x.teach:T.teach,keep:x?x.keep:T.keep,en:(x?x.en:T.en).slice(0,3).concat([X?X.L4:L4.en]),
  verse:l==='en'?iast:dev.map(d=>devTo(d,l)),dev:dev,iast:iast,roman:l==='en',
  words:T.words.map((w,i)=>[w[0],x&&x.words[i]?x.words[i]:w[1]])};}
// changing language reloads the page, so every screen comes back fully in the new language
function setLang(l,noReload){if(!LANGS.some(x=>x[0]===l))return;const was=lang();LANG=l;try{localStorage.setItem('tr-lang',JSON.stringify(l));}catch(e){}
 document.documentElement.lang=l;if(!noReload&&l!==was){location.reload();return;}applyI18n();window.dispatchEvent(new Event('langchange'));}
/* Screen translator: text in the app is written in English; when another language is on, any text node (and placeholder,
   aria-label, title) whose whole text matches the table is swapped as it appears. English tattva names, teachings and
   meanings are added to the table from TI18N, and a few patterns handle text with numbers in it. User content opts out
   with data-notr. */
(function(){
 ['te','kn','hi'].forEach(l=>{const D=UI18N[l]||(UI18N[l]={}),X=TI18N[l];if(!X)return;
  TATTVAS.forEach((T,i)=>{const x=X.t[i];if(!x)return;D[T.name]=x.name;D[T.teach]=x.teach;T.keep.forEach((k,j)=>D[k]=x.keep[j]);T.en.forEach((e,j)=>D[e]=x.en[j]);T.words.forEach((w,j)=>{if(x.words[j])D[w[1]]=x.words[j];});});D[L4.en]=X.L4;});})();
const UIPAT={};
['te','kn','hi'].forEach(l=>{const D=UI18N[l],tv=D['Tattva']||'Tattva';
 UIPAT[l]=[[/^Tattva (\d)$/,tv+' $1'],[/^Tattva (\d) · (.+)$/,(m,n,name)=>tv+' '+n+' · '+(D[name]||name)],[/^Tattva (\d): (.+)$/,(m,n,name)=>tv+' '+n+': '+(D[name]||name)],
  [/^(\d+)s$/,'$1s'],[/^Start · (\d+) seconds$/,(m,n)=>(D['Start']||'Start')+' · '+n+'s']];});
function trText(v){if(!LANG||LANG==='en')return null;const k=v.trim();if(!k||k.length>400)return null;const D=UI18N[LANG];
 if(D[k])return v.replace(k,D[k]);for(const p of UIPAT[LANG]||[])if(p[0].test(k))return v.replace(k,k.replace(p[0],p[1]));return null;}
function trEl(el){if(!LANG||LANG==='en'||!el)return;if(el.nodeType===3){const p=el.parentNode;if(p&&p.closest&&p.closest('[data-notr],script,style,svg'))return;const r=trText(el.nodeValue);if(r!=null&&r!==el.nodeValue)el.nodeValue=r;return;}
 if(el.nodeType!==1||el.closest('[data-notr],script,style'))return;
 const at=n=>{['placeholder','aria-label','title'].forEach(a=>{const v=n.getAttribute&&n.getAttribute(a);if(v){const r=trText(v);if(r!=null&&r!==v)n.setAttribute(a,r);}});};
 at(el);el.querySelectorAll('[placeholder],[aria-label],[title]').forEach(at);
 const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;const list=[];while((n=w.nextNode()))list.push(n);list.forEach(trEl);}
function startTranslator(){if(!LANG||LANG==='en')return;document.documentElement.lang=LANG;trEl(document.body);
 new MutationObserver(ms=>{for(const m of ms){if(m.type==='characterData')trEl(m.target);else{m.addedNodes.forEach(trEl);if(m.type==='attributes')trEl(m.target);}}})
  .observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['placeholder','aria-label','title']});}
// static text in the markup carries data-t="English text"
function applyI18n(root){(root||document).querySelectorAll('[data-t]').forEach(el=>{el.textContent=LX(el.dataset.t);});
 (root||document).querySelectorAll('[data-tp]').forEach(el=>{el.setAttribute('placeholder',LX(el.dataset.tp));});
 (root||document).querySelectorAll('[data-ta]').forEach(el=>{el.setAttribute('aria-label',LX(el.dataset.ta));});}
